'use strict';
(()=>{const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;},check=r=>{if(r.error)throw Error(r.error.message);return r.data;},button=(text,fn,cls)=>{const n=el('button',text,cls);n.type='button';n.onclick=fn;return n;},stamp=t=>new Date(t).toLocaleString('en-CA',{timeZone:'America/Toronto'});const emojis=[['👍','Like'],['❤️','Love'],['🎉','Celebrate'],['👏','Applaud'],['💡','Insightful'],['✅','Acknowledged']];
function field(root,label,type,value){const wrap=el('label',label,'portal-field'),input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=value||'';wrap.append(input);root.append(wrap);return input;}
function editor(root,team,api,kind,onSaved,item){root.replaceChildren();const form=el('form',undefined,'portal-form community-editor'),title=field(form,'Post title','text',item?.title),body=field(form,'Message','textarea',item?.body),save=el('button',item?'Save changes':'Publish post','primary'),status=el('p',undefined,'portal-note');title.maxLength=160;body.maxLength=12000;title.required=body.required=true;save.type='submit';status.setAttribute('role','status');form.append(save,button('Cancel',()=>root.replaceChildren()),status);root.append(el('h2',kind==='company'?'Company announcement':kind==='team_announcement'?'Team announcement':'Start a discussion'),form);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const id=check(await api.db.rpc('save_community_post',{record:{id:item?.id,team_id:kind==='company'?null:team,kind,title:title.value.trim(),body:body.value.trim()}}));window.GuhuzaNotices?.refresh();await onSaved(id);}catch(e){status.textContent=e.message;}finally{save.disabled=false;}};}
function reactions(root,post,comment,data,api,refresh){const row=el('div',undefined,'community-reactions');for(const [emoji,label]of emojis){const current=(data||[]).find(r=>r.emoji===emoji),b=button(emoji+(current?.count?' '+current.count:''),async()=>{b.disabled=true;try{check(await api.db.rpc('toggle_community_reaction',{target_post:post,target_comment:comment||null,reaction:emoji}));await refresh();}catch(e){root.append(el('p',e.message,'portal-note'));}finally{b.disabled=false;}},'community-reaction');b.setAttribute('aria-label',label+(current?.count?', '+current.count+' reactions':''));b.setAttribute('aria-pressed',String(!!current?.mine));row.append(b);}root.append(row);}
async function render({root,team,api,state}){const tab=state.communityTab||'company',offset=Math.max(0,Number(state.communityPage)||0),refresh=()=>GuhuzaTeams.open({...state,view:'announcements',team}),openPost=(id,kind)=>GuhuzaTeams.open({view:'announcements',team,communityTab:kind==='company'?'company':'team',post:id});root.append(el('p','GUHUZA COMMUNITY','eyebrow'),el('h1','Announcements & discussions'),el('p','Company news, team updates and conversations. Keep posts helpful and respectful.','portal-description'));if(!state.post)window.Gerrie?.banner(root,'tip','Good ideas start a conversation.','Read the latest announcements, share a useful update and let your teammates know you have seen their post with a comment or reaction.');const tabs=el('nav',undefined,'learning-tabs');tabs.setAttribute('aria-label','Announcement areas');for(const [key,label]of [['company','Company announcements'],...(team?[['team','Team discussion board']]:[])]){const b=button(label,()=>GuhuzaTeams.open({view:'announcements',team,communityTab:key}));b.setAttribute('aria-pressed',String(tab===key));tabs.append(b);}root.append(tabs);let feed;
if(state.post){const thread=check(await api.db.rpc('community_thread',{target_post:state.post,page_offset:Math.max(0,Number(state.commentPage)||0)}));root.append(button('← Back to '+(thread.post.kind==='company'?'company announcements':'team board'),()=>GuhuzaTeams.open({view:'announcements',team,communityTab:thread.post.kind==='company'?'company':'team'}),'portal-text-button'));postCard(root,thread.post,true);const comments=el('section',undefined,'community-comments');comments.append(el('h2','Comments ('+thread.post.comments+')'));for(const c of thread.comments){const card=el('article',undefined,'community-comment');card.append(el('strong',c.author),el('small',stamp(c.created_at)),el('p',c.body,'community-body'));reactions(card,thread.post.id,c.id,c.reactions,api,refresh);if(c.can_delete)card.append(button('Delete comment',async()=>{if(!confirm('Delete this comment?'))return;try{check(await api.db.rpc('delete_community_content',{target_post:thread.post.id,target_comment:c.id}));await refresh();}catch(e){card.append(el('p',e.message,'portal-note'));}},'portal-text-button'));comments.append(card);}const page=Number(state.commentPage)||0,nav=el('div',undefined,'actions');if(page>0)nav.append(button('Previous comments',()=>GuhuzaTeams.open({...state,commentPage:Math.max(0,page-20)})));if(page+20<thread.post.comments)nav.append(button('More comments',()=>GuhuzaTeams.open({...state,commentPage:page+20})));comments.append(nav);const form=el('form',undefined,'portal-form'),body=field(form,'Add a comment','textarea'),send=el('button','Post comment','primary'),status=el('p',undefined,'portal-note');body.required=true;body.maxLength=5000;send.type='submit';status.setAttribute('role','status');form.append(send,status);comments.append(form);root.append(comments);form.onsubmit=async e=>{e.preventDefault();send.disabled=true;try{check(await api.db.rpc('add_community_comment',{target_post:thread.post.id,comment_body:body.value.trim()}));window.GuhuzaNotices?.refresh();await GuhuzaTeams.open({...state,commentPage:Math.floor(thread.post.comments/20)*20});}catch(e){status.textContent=e.message;}finally{send.disabled=false;}};return;}
feed=check(await api.db.rpc('community_feed',{target_team:team||null,feed:tab,page_offset:offset}));const composer=el('div'),actions=el('div',undefined,'learning-tabs');if(tab==='company'&&feed.can_company)actions.append(button('New company announcement',()=>editor(composer,team,api,'company',id=>openPost(id,'company')),'primary'));if(tab==='team'){if(feed.can_staff)actions.append(button('New team announcement',()=>editor(composer,team,api,'team_announcement',id=>openPost(id,'team_announcement')),'primary'));actions.append(button('Start a discussion',()=>editor(composer,team,api,'discussion',id=>openPost(id,'discussion'))));}root.append(actions,composer);if(tab==='company')root.append(el('p','Admins publish company announcements. Everyone can comment and react.','portal-note'));else root.append(el('p','Team announcements from leads and admins are highlighted. Everyone on this team can start a discussion.','portal-note'));for(const p of feed.items)postCard(root,p,false);if(!feed.items.length)root.append(el('p',tab==='company'?'No company announcements yet.':'No team posts yet. Start the conversation.','community-empty'));const pages=el('div',undefined,'actions');if(offset>0)pages.append(button('Newer posts',()=>GuhuzaTeams.open({...state,communityPage:Math.max(0,offset-20)})));if(offset+20<feed.total)pages.append(button('Older posts',()=>GuhuzaTeams.open({...state,communityPage:offset+20})));root.append(pages);
function postCard(container,p,full){const card=el('article',undefined,'community-post '+(p.kind==='discussion'?'discussion-post':'staff-post')),head=el('div',undefined,'community-post-meta'),label=p.kind==='company'?'Company announcement':p.kind==='team_announcement'?'Team announcement':'Discussion';head.append(el('span',label,'community-kind'),el('span',p.author),el('span',p.author_role,'community-author-role'),el('time',stamp(p.created_at)));card.append(head,el('h2',p.title),el('p',full?p.body:p.body.length>450?p.body.slice(0,450)+'…':p.body,'community-body'));if(!full)card.append(button('Open '+(p.kind==='discussion'?'discussion':'announcement')+' · '+p.comments+' comments',()=>openPost(p.id,p.kind),'portal-text-button'));reactions(card,p.id,null,p.reactions,api,refresh);const holder=el('div');if(full){const tools=el('div',undefined,'learning-tabs');if(p.can_edit)tools.append(button('Edit post',()=>editor(holder,p.team_id,api,p.kind,()=>refresh(),p)));if(p.can_delete)tools.append(button('Delete post',async()=>{if(!confirm('Delete this post and hide its conversation?'))return;try{check(await api.db.rpc('delete_community_content',{target_post:p.id,target_comment:null}));window.GuhuzaNotices?.refresh();await GuhuzaTeams.open({view:'announcements',team,communityTab:p.kind==='company'?'company':'team'});}catch(e){holder.append(el('p',e.message,'portal-note'));}},'portal-text-button'));card.append(tools,holder);}container.append(card);}
}
async function adminRender({root,team,api}){const targets=check(await api.db.rpc('announcement_admin_targets'));root.append(el('p','ADMIN ANNOUNCEMENTS','eyebrow'),el('h1','Publish an announcement'),el('p','Choose the whole company or one of the teams you administer. Other teams are not available here.','portal-description'));const form=el('form',undefined,'portal-form community-editor'),label=el('label','Audience','portal-field'),audience=el('select');for(const [id,name]of [['company','Whole company'],...targets.teams.map(t=>[t.id,t.name])]){const o=el('option',name);o.value=id;audience.append(o);}audience.value=targets.teams.some(t=>t.id===team)?team:'company';label.append(audience);form.append(label);const hint=el('p',undefined,'portal-note'),title=field(form,'Announcement title','text'),body=field(form,'Announcement message','textarea'),save=el('button','Publish announcement','primary'),status=el('p',undefined,'portal-note');title.required=body.required=true;title.maxLength=160;body.maxLength=12000;status.setAttribute('role','status');save.type='submit';const update=()=>{hint.textContent=audience.value==='company'?'Every active account will receive a company-announcement notification.':'Members of '+(targets.teams.find(t=>t.id===audience.value)?.name||'this team')+' will receive a team-announcement notification.';};audience.onchange=update;update();form.append(hint,save,status);root.append(form);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const company=audience.value==='company',id=check(await api.db.rpc('save_community_post',{record:{kind:company?'company':'team_announcement',team_id:company?null:audience.value,title:title.value.trim(),body:body.value.trim()}}));window.GuhuzaNotices?.refresh();await GuhuzaTeams.open({view:'announcements',team:company?team||undefined:audience.value,communityTab:company?'company':'team',post:id});}catch(e){status.textContent=e.message;}finally{save.disabled=false;}};}
window.GuhuzaCommunity={render,adminRender};})();
